head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 1

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDINS16600.xml";
scwin.cnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 투자계약증권 표준코드관리  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    if ((txb_pSTD_CD.getValue() == "" || txb_pSTD_CD.getValue().indexOf(" ") == "") &&
        (txb_pISU_NM.getValue() == "" || txb_pISU_NM.getValue().indexOf(" ") == "") &&
        (txb_pISUR_CD.getValue() == "" || txb_pISUR_CD.getValue().indexOf(" ") == "") &&
        (edt_pSTD_CD_GRNT_DD_SDATE.getValue() == "" || edt_pSTD_CD_GRNT_DD_SDATE.text.indexOf(" ") == "") &&
        (edt_pSTD_CD_GRNT_DD_EDATE.getValue() == "" || edt_pSTD_CD_GRNT_DD_EDATE.text.indexOf(" ") == "")) {
        $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }

    //데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS16600_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdInvestInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ISU_DD_SDATE=" + edt_pISU_DD_SDATE.getValue() + "&{P}ISU_DD_EDATE=" + edt_pISU_DD_EDATE.getValue() + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 수익증권 표준코드관리 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    //데이터셋 초기화
    dts_detail.removeAll();

    // 수익증권 표준코드관리
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS16600_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.readStdCdInvestInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};



/********************************************** 
 * 함수명   : ins_modify	
 * 설명       : 투자계약증권 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_modify = function(mflag) {
    var screenProcsTpCd = "03";
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if (txb_ISU_KOR_NM.getValue() == "" || txb_ISU_KOR_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 80, "한글종목명")) {
            //txb_ISU_NM.value = "";
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (txb_ISU_KOR_ABBRV.getValue() == "" || txb_ISU_KOR_ABBRV.getValue().indexOf(" ") == "" || txb_ISU_KOR_ABBRV.getValue() == " ") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 40, "한글종목약명")) {
            //txb_ISU_KOR_ABBRV.value = "";
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            //txb_ISU_ENG_NM.value = "";
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "" || txb_ISU_ENG_ABBRV.getValue() == " ") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            //txb_ISU_ENG_ABBRV.value = "";
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (txb_JNT_BZ_NM.getValue() == "" || txb_JNT_BZ_NM.getValue().indexOf(" ") == "" || txb_JNT_BZ_NM.getValue() == " ") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "공동사업명"));
            txb_JNT_BZ_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_JNT_BZ_NM, 60, "공동사업명")) {
            txb_JNT_BZ_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_AMT) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행금액"));
            edt_ISU_AMT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_CURR_TP_CD) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행통화"));
            cmb_CURR_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_ISU_TP_CD) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행구분"));
            cmb_ISU_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_INVST_CONTRT_ISU_METHD_TP_CD) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행방법"));
            cmb_INVST_CONTRT_ISU_METHD_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_CONTRT_STRT_DD) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "계약시작일자"));
            edt_CONTRT_STRT_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_CONTRT_END_DD) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "계약종료일자"));
            edt_CONTRT_END_DD.focus();
            return false;
        }
        //날짜포맷 체크
        if (fn_CheckDateObj(edt_CONTRT_STRT_DD, "계약시작일자")) return false;
        if (fn_CheckDateObj(edt_CONTRT_END_DD, "계약종료일자")) return false;
        if ($c.stf.getObjectValue(cmb_CRWFND_YN) == "") {
            tab_UsrInfo.setSelectedTabIndex(1);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "크라우드펀딩여부"));
            cmb_CRWFND_YN.focus();
            return false;
        }
        if (txb_PL_REVR_REL_CONTN.getValue() == "" || txb_PL_REVR_REL_CONTN.getValue().indexOf(" ") == "" || txb_PL_REVR_REL_CONTN.getValue() == " ") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "손익귀속관련사항"));
            txb_PL_REVR_REL_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_PL_REVR_REL_CONTN, 60, "손익귀속관련사항")) {
            txb_PL_REVR_REL_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_SPECL_CONTRT_CONTN, 60, "특약사항")) {
            txb_SPECL_CONTRT_CONTN.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MEMO_CONTN, 200, "담당자메모")) {
            txb_MEMO_CONTN.focus();
            return false;
        }
        if (mflag == "N") return;
        dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
        trs_modify.Action = "/StdCdInvestInfoAction.do?method=modifyStdCdInvestInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_modify.KeyName = "toinb_dataid4";
        trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInputMaster=dts_detail)";
        trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
        trs_modify.Post();
    }
};



/********************************************** 
 * 함수명   : ins_remove	
 * 설명       : 표준코드 삭제
 ***********************************************/
scwin.ins_remove = function() {
    var screenProcsTpCd = "04";
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.Action = "/StdCdInvestInfoAction.do?method=removeStdCdInvestInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_Delete.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Delete.Post();
};


/********************************************** 
 * 함수명   : Change_mf_cfi
 * 설명       : 증권투자회사/부동산투자회사의 cfi 변경 설정
 ***********************************************/
scwin.Change_mf_cfi = function() {
    //
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "EU";
    if ($c.stf.getObjectValue(cmb_mf_cfi_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_mf_cfi_attr_1);
    if ($c.stf.getObjectValue(cmb_mf_cfi_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_mf_cfi_attr_2);
    if ($c.stf.getObjectValue(cmb_mf_cfi_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_mf_cfi_attr_3);
    if ($c.stf.getObjectValue(cmb_mf_cfi_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_mf_cfi_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    scwin.arrPar[1] = txb_param2.getValue();

    //alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.fn_set_fn_GetParam = function(vparam1) {
    txb_param1.setValue(vparam1);
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    //PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_6);

    txb_pSTD_CD.setValue("KRH");
    ins_combo_set(dts_CURR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475", "SEL"); //발행통화코드
    ins_combo_set(dts_ISU_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03407", "SEL"); //발행구분(국내/해외)//03869
    ins_combo_set(dts_INVST_CONTRT_ISU_METHD_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03348", "SEL"); //투자계약증권발행방법
    ins_combo_set(dts_COM_ATTR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00840", "SEL"); //회사속성
    ins_combo_set(dts_STD_CD_APCT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03527"); //03527 - 신청자구분 
    fn_CtrlBtn_temp("no_data");
    $c.stf.showObj(txb_DEL_RSN, false);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txa_REF_CONTN, false);

    //2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    $c.stf.showObj(btn_clearPwd, false);
    //2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    var arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (var i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드 
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "590", "420");
};
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데.. 
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(dts_detail.getCellData(1, "STD_CD_APPL_ID")); // 표준코드 신청 ID  
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.img_CONTRT_STRT_DD_onclick = function() {
    popUpCalendar2(edt_ISU_DD);
};
scwin.img_CONTRT_END_DD_onclick = function() {
    popUpCalendar2(edt_EXP_DD);
};
scwin.img_COM_NM_INFO_onclick = function() {
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관코드 
    txb_param2.setValue(txb_ISUR_NM.getValue()); // 발행기관명  
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "740", "835");
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    fn_CtrlBtn_temp("no_data");
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    fn_CtrlBtn_temp("update");
    if (dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD") == "Y") {
        //alert(" 상장종목은 수정할 수 없습니다. \n 공시총괄팀과 협의하시기 바랍니다.");
        btn_modify.setDisabled(true);
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/ins/btn_delete_d.gif";

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
    }
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_search();
};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_search();
};
scwin.btn_delete_onclick = function() {
    //if (fn_checkSendTime()==false) { alert("정보문의 전송 마감시간(19:00)이 초과되어 삭제하실수 없습니다."); return; }
    txb_param1.setValue("");
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    // 삭제 신청건수 확인후 
    var DELCNT = dts_detail.getCellData(dts_detail.rowpositon, "DELCNT");
    if (eval(DELCNT) > 0) {
        // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제 
        fn_alertRequiredDelByWeb();
    } else {
        // 관리 삭제로직 
        // 삭제팝업호출 
        //삭제사유 전달받을 input박스 정의한다.
        var rtn = fn_alertDelConfirm();
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
        }
        //ins_remove() 함수를 자동호출 하므로 삭제 함수를 만들어 두어야 한다.

    }
};
